@push('scripts')<script>
const variants=@json($variantData);
document.querySelectorAll('[data-gallery-src]').forEach(x=>x.addEventListener('click',()=>{document.getElementById('main-image').src=x.dataset.gallerySrc;document.querySelectorAll('.gallery-thumb').forEach(t=>t.classList.remove('active'));x.classList.add('active')}));
document.querySelectorAll('input[name=color],input[name=size]').forEach(x=>x.addEventListener('change',()=>{const c=document.querySelector('input[name=color]:checked')?.value,s=document.querySelector('input[name=size]:checked')?.value,box=document.getElementById('variant-status');if(!c||!s)return;const v=variants.find(x=>x.color===c&&x.size===s),valid=v&&v.stock>0;box.textContent=!v?'Không có biến thể này.':valid?`Còn ${v.stock} sản phẩm · SKU ${v.sku}`:'Biến thể này đã hết hàng.';box.className='variant-status mb-3 '+(valid?'text-success':'text-danger');const id=document.getElementById('variant-id'),qty=document.getElementById('cart-quantity');if(id)id.value=valid?v.id:'';if(qty)qty.max=v?.stock||1;['add-cart','buy-now'].forEach(k=>{const b=document.getElementById(k);if(b)b.disabled=!valid})}));
document.getElementById('suggest-size').addEventListener('click',()=>{const h=+document.getElementById('height').value,w=+document.getElementById('weight').value;let s=w<=55&&h<=165?'S':w<=65&&h<=172?'M':w<=75&&h<=178?'L':w<=88&&h<=188?'XL':'XXL';document.getElementById('size-result').innerHTML=h&&w?`Size gợi ý: <strong>${s}</strong>`:'Vui lòng nhập đủ chiều cao và cân nặng.'});
</script>@endpush
